class Solution {
public:
    int maxContainers(int n, int w, int maxWeight) {
        long long cnt = 0;
        while (cnt < (long long)n * n && (cnt + 1) * (long long)w <= maxWeight) cnt++;
        return (int)cnt;
    }
};

